(() => {
  const t = (document.body ? document.body.innerText : "").slice(0, 900);
  const inputs = Array.from(document.querySelectorAll("input")).map(i => ({type:i.type, id:i.id, name:i.name, ph:i.placeholder}));
  const buttons = Array.from(document.querySelectorAll("button,a")).map(b => (b.innerText||"").trim()).filter(t => t && t.length < 40).slice(0, 30);
  return JSON.stringify({url: location.href, title: document.title, t, inputs, buttons});
})()
